/**
 *  Pages Authentication
 */

"use strict";
const formAuthentication = document.querySelector("#formAuthentication");

$('#formAuthentication :input[type="email"]').keyup(function () {
    this.value = this.value.toLowerCase();
});

$('#formAuthentication :input[type="password"]').keypress(function (e) {
    if (e.which === 32) return false;
});

document.addEventListener("DOMContentLoaded", function (e) {
    (function () {
        // Form validation for Add new record
        if (formAuthentication) {
            const fv = FormValidation.formValidation(formAuthentication, {
                fields: {
                    email: {
                        validators: {
                            notEmpty: {
                                message: "Masukan alamat email",
                            },
                            emailAddress: {
                                message: "Masukan alamat email yang terdaftar",
                            },
                        },
                    },
                    password: {
                        validators: {
                            notEmpty: {
                                message: "Masukan password",
                            },
                            stringLength: {
                                min: 6,
                                message: "Password harus lebih dari 6 karakter",
                            },
                        },
                    },
                    "confirm-password": {
                        validators: {
                            notEmpty: {
                                message: "Konfirmasi password",
                            },
                            identical: {
                                compare: function () {
                                    return formAuthentication.querySelector(
                                        '[name="password"]',
                                    ).value;
                                },
                                message: "Konfirmasi password tidak sesuai",
                            },
                            stringLength: {
                                min: 6,
                                message: "Password harus lebih dari 6 karakter",
                            },
                        },
                    },
                },
                plugins: {
                    trigger: new FormValidation.plugins.Trigger(),
                    bootstrap5: new FormValidation.plugins.Bootstrap5({
                        eleValidClass: "",
                        rowSelector: ".mb-3",
                    }),
                    submitButton: new FormValidation.plugins.SubmitButton(),
                    defaultSubmit: new FormValidation.plugins.DefaultSubmit(),
                    autoFocus: new FormValidation.plugins.AutoFocus(),
                },
                init: (instance) => {
                    instance.on("plugins.message.placed", function (e) {
                        if (
                            e.element.parentElement.classList.contains(
                                "input-group",
                            )
                        ) {
                            e.element.parentElement.insertAdjacentElement(
                                "afterend",
                                e.messageElement,
                            );
                        }
                    });
                },
            }).on("core.form.validating", function () {
                $.unblockUI();
            });

            const base64Logo =
                "data:image/png;base64,";

            $(formAuthentication).on("submit", function (e) {
                e.preventDefault();
                fv.validate().then(function (status) {
                    if (status === "Valid") {
                        $.blockUI({
                            message: `
                                <div class="d-flex flex-column align-items-center justify-content-center">
                                <!-- Kontainer utama sedikit dinaikkan ke 45px -->
                                    <div class="position-relative d-flex align-items-center justify-content-center" style="width: 45px; height: 45px; margin: 0 auto 10px auto;">
                            
                                        <!-- 1. Loader SpinKit dengan Padding agar titik berputar di tepi luar -->
                                        <div class="sk-chase" style="width: 100%; height: 100%; position: absolute; padding: 2px; box-sizing: border-box;"> 
                                            <div class="sk-chase-dot"></div> 
                                            <div class="sk-chase-dot"></div> 
                                            <div class="sk-chase-dot"></div> 
                                            <div class="sk-chase-dot"></div> 
                                            <div class="sk-chase-dot"></div> 
                                            <div class="sk-chase-dot"></div> 
                                        </div>

                                        <!-- 2. Custom Logo (Statis di Tengah, Tidak Ikut Berputar) -->
                                        <img src="${base64Logo}" alt="Logo" style="width: 40px; height: 40px; object-fit: contain; z-index: 10; position: relative;">
                            
                                    </div>
                                </div>
                            `,
                            css: {
                                backgroundColor: "transparent",
                                color: "#fff",
                                border: "0",
                            },
                            overlayCSS: {
                                backgroundColor: $("html").hasClass(
                                    "dark-style",
                                )
                                    ? "#000"
                                    : "#000",
                                opacity: 0.75,
                            },
                        });
                    }
                });
            });
        }

        //  Two Steps Verification
        const numeralMask = document.querySelectorAll(".numeral-mask");

        // Verification masking
        if (numeralMask.length) {
            numeralMask.forEach((e) => {
                new Cleave(e, {
                    numeral: true,
                });
            });
        }
    })();
});
